export const a = (x: number): number => Math.sin(x);
export const b = (x: number): number => Math.sqrt(x);
export const c = (x: number): number => Math.pow(x, 2);
export const d = (x: number): number => Math.cos(x) + Math.tan(x);
export const e = Math.PI;
export const f = (x: number): number => Math.floor(x);
